package gateway

const dashboardHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow"><title>pibase dashboard</title>
<style>:root{font:14px system-ui;color:#e8edf5;background:#0c1220}body{max-width:1100px;margin:auto;padding:28px}header{display:flex;justify-content:space-between;align-items:center}input,textarea,select,button{font:inherit;color:inherit;background:#151e31;border:1px solid #34405a;border-radius:7px;padding:8px}input{width:260px}button{cursor:pointer}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin:24px 0}.card,.sql{background:#131b2d;border:1px solid #29344b;border-radius:10px;padding:16px}.muted{color:#8d99ae}.big{font-size:24px;margin-top:6px}textarea{box-sizing:border-box;width:100%;height:150px;font-family:ui-monospace,monospace;margin:10px 0}pre{overflow:auto;white-space:pre-wrap}.danger{color:#ff9696}</style></head>
<body><header><div><h1>pibase</h1><span class="muted">Operations dashboard</span></div><div><input id="token" type="password" placeholder="Operator token"><button id="load">Load</button></div></header>
<div id="summary" class="grid"></div><section class="sql"><h2>Owner SQL</h2><p class="muted">Runs as the selected project admin with a 30-second timeout and 1,000-row result cap. Operator access only.</p><select id="project"></select><textarea id="sql" spellcheck="false">select current_user, now();</textarea><button id="run">Run SQL</button><pre id="result"></pre></section>
<p id="error" class="danger"></p><script>
const q=id=>document.getElementById(id), auth=()=>({'Authorization':'Bearer '+q('token').value,'Content-Type':'application/json'}), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function bytes(n){for(const u of ['B','KiB','MiB','GiB']){if(n<1024)return n.toFixed(1)+' '+u;n/=1024}return n.toFixed(1)+' TiB'}
async function load(){try{const r=await fetch('/_pibase/projects',{headers:auth()});if(!r.ok)throw Error(await r.text());const ps=await r.json();q('summary').innerHTML=ps.map(p=>'<article class="card"><b>'+esc(p.name)+'</b><div class="muted">'+esc(p.id)+'</div><div class="big">'+bytes(p.database_bytes+p.storage_bytes)+'</div><div class="muted">DB '+bytes(p.database_bytes)+' · files '+bytes(p.storage_bytes)+' · '+p.requests_30d+' requests/30d</div></article>').join('');q('project').innerHTML=ps.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' ('+esc(p.id)+')</option>').join('');q('error').textContent=''}catch(e){q('error').textContent=e.message}}
async function run(){try{q('result').textContent='Running…';const r=await fetch('/_pibase/projects/'+encodeURIComponent(q('project').value)+'/sql',{method:'POST',headers:auth(),body:JSON.stringify({sql:q('sql').value})});const t=await r.text();if(!r.ok)throw Error(t);q('result').textContent=JSON.stringify(JSON.parse(t),null,2)}catch(e){q('result').textContent=e.message}}
q('load').onclick=load;q('run').onclick=run;</script></body></html>`
